"""Date ranges, see SPEC.md."""
import calendar
import datetime
import re


_DATE_RE = re.compile(r"([0-9]{4})-([0-9]{2})-([0-9]{2})")
_MONTH_RE = re.compile(r"([0-9]{4})-([0-9]{2})")
_WEEK_RE = re.compile(r"([0-9]{4})-W([0-9]{2})")
_YEAR_RE = re.compile(r"([0-9]{4})")


def parse_range(text):
    """Parse an inclusive date range as described in SPEC.md."""
    if not isinstance(text, str):
        raise ValueError("date range must be text")

    value = text.strip(" ")
    if not value:
        raise ValueError("date range is empty")

    if ".." not in value:
        return _parse_standalone(value)

    left, _, right = value.partition("..")
    if ".." in right:
        raise ValueError("invalid date range: {!r}".format(text))

    left = left.strip(" ")
    right = right.strip(" ")
    if not left and not right:
        raise ValueError("date range must have at least one end")

    start = _parse_date(left) if left else None
    end = _parse_date(right) if right else None
    if start is not None and end is not None and end < start:
        raise ValueError("range end precedes range start")
    return start, end


def _parse_standalone(value):
    if _DATE_RE.fullmatch(value):
        day = _parse_date(value)
        return day, day

    match = _MONTH_RE.fullmatch(value)
    if match:
        year, month = (int(part) for part in match.groups())
        try:
            first = datetime.date(year, month, 1)
            last = datetime.date(year, month, calendar.monthrange(year, month)[1])
        except ValueError:
            raise ValueError("invalid month: {!r}".format(value)) from None
        return first, last

    match = _WEEK_RE.fullmatch(value)
    if match:
        year, week = (int(part) for part in match.groups())
        try:
            return (
                datetime.date.fromisocalendar(year, week, 1),
                datetime.date.fromisocalendar(year, week, 7),
            )
        except ValueError:
            raise ValueError("invalid ISO week: {!r}".format(value)) from None

    match = _YEAR_RE.fullmatch(value)
    if match:
        year = int(match.group(1))
        try:
            return datetime.date(year, 1, 1), datetime.date(year, 12, 31)
        except ValueError:
            raise ValueError("invalid year: {!r}".format(value)) from None

    raise ValueError("invalid date range: {!r}".format(value))


def _parse_date(value):
    match = _DATE_RE.fullmatch(value)
    if not match:
        raise ValueError("invalid ISO date: {!r}".format(value))
    year, month, day = (int(part) for part in match.groups())
    try:
        return datetime.date(year, month, day)
    except ValueError:
        raise ValueError("invalid ISO date: {!r}".format(value)) from None

import datetime
import unittest

from daterange import parse_range


def date(year, month, day):
    return datetime.date(year, month, day)


class TestDateRange(unittest.TestCase):
    def assertInvalid(self, text):
        with self.assertRaises(ValueError):
            parse_range(text)

    def test_two_dates(self):
        self.assertEqual(
            parse_range("2026-10-01..2026-10-31"),
            (date(2026, 10, 1), date(2026, 10, 31)),
        )

    def test_same_day_range(self):
        self.assertEqual(
            parse_range("2026-10-01..2026-10-01"),
            (date(2026, 10, 1), date(2026, 10, 1)),
        )

    def test_leap_day_range(self):
        self.assertEqual(
            parse_range("2024-02-29..2024-03-01"),
            (date(2024, 2, 29), date(2024, 3, 1)),
        )

    def test_end_before_start_is_invalid(self):
        self.assertInvalid("2026-10-31..2026-10-01")

    def test_month(self):
        self.assertEqual(
            parse_range("2026-10"),
            (date(2026, 10, 1), date(2026, 10, 31)),
        )
        self.assertEqual(
            parse_range("2026-04"),
            (date(2026, 4, 1), date(2026, 4, 30)),
        )
        self.assertEqual(
            parse_range("2026-12"),
            (date(2026, 12, 1), date(2026, 12, 31)),
        )

    def test_february(self):
        self.assertEqual(
            parse_range("2024-02"),
            (date(2024, 2, 1), date(2024, 2, 29)),
        )
        self.assertEqual(
            parse_range("2025-02"),
            (date(2025, 2, 1), date(2025, 2, 28)),
        )

    def test_invalid_month(self):
        for text in ("2026-13", "2026-00", "2026-1", "0000-01"):
            with self.subTest(text=text):
                self.assertInvalid(text)

    def test_iso_week(self):
        self.assertEqual(
            parse_range("2026-W44"),
            (date(2026, 10, 26), date(2026, 11, 1)),
        )

    def test_iso_week_crossing_year(self):
        self.assertEqual(
            parse_range("2026-W01"),
            (date(2025, 12, 29), date(2026, 1, 4)),
        )

    def test_iso_week_53(self):
        self.assertEqual(
            parse_range("2026-W53"),
            (date(2026, 12, 28), date(2027, 1, 3)),
        )

    def test_invalid_week(self):
        for text in ("2026-W54", "2026-W00", "2026-W1", "2026-w44", "0000-W01"):
            with self.subTest(text=text):
                self.assertInvalid(text)

    def test_year(self):
        self.assertEqual(
            parse_range("2026"),
            (date(2026, 1, 1), date(2026, 12, 31)),
        )
        self.assertEqual(
            parse_range("2024"),
            (date(2024, 1, 1), date(2024, 12, 31)),
        )
        self.assertEqual(
            parse_range("9999"),
            (date(9999, 1, 1), date(9999, 12, 31)),
        )

    def test_invalid_year(self):
        self.assertInvalid("0000")

    def test_open_start(self):
        self.assertEqual(
            parse_range("..2026-10-01"),
            (None, date(2026, 10, 1)),
        )

    def test_open_end(self):
        self.assertEqual(
            parse_range("2026-10-01.."),
            (date(2026, 10, 1), None),
        )

    def test_open_at_both_ends_is_invalid(self):
        for text in ("..", " .. ", "...."):
            with self.subTest(text=text):
                self.assertInvalid(text)

    def test_spaces_around_text(self):
        self.assertEqual(
            parse_range("  2026-10-01..2026-10-31  "),
            (date(2026, 10, 1), date(2026, 10, 31)),
        )
        self.assertEqual(
            parse_range(" 2026-10 "),
            (date(2026, 10, 1), date(2026, 10, 31)),
        )
        self.assertEqual(
            parse_range(" 2026-W44 "),
            (date(2026, 10, 26), date(2026, 11, 1)),
        )
        self.assertEqual(
            parse_range(" 2026 "),
            (date(2026, 1, 1), date(2026, 12, 31)),
        )

    def test_spaces_around_separator(self):
        self.assertEqual(
            parse_range("2026-10-01 .. 2026-10-31"),
            (date(2026, 10, 1), date(2026, 10, 31)),
        )
        self.assertEqual(
            parse_range("2026-10-01  ..  2026-10-31"),
            (date(2026, 10, 1), date(2026, 10, 31)),
        )
        self.assertEqual(
            parse_range("2026-10-01 .. "),
            (date(2026, 10, 1), None),
        )
        self.assertEqual(
            parse_range(" .. 2026-10-01"),
            (None, date(2026, 10, 1)),
        )

    def test_empty_input_is_invalid(self):
        for text in ("", " ", "   "):
            with self.subTest(text=text):
                self.assertInvalid(text)

    def test_invalid_dates(self):
        for text in (
            "2026-02-30",
            "2026-02-29",
            "2026-13-01",
            "2026-00-10",
            "2026-01-00",
            "2026-1-01",
            "26-01-01",
            "2026-01-1",
            "2026-01-011",
            "2026/01/01",
        ):
            with self.subTest(text=text):
                self.assertInvalid(text)

    def test_single_iso_date_is_invalid(self):
        self.assertInvalid("2026-10-01")

    def test_other_forms_cannot_be_range_ends(self):
        for text in ("2026-10..2026-12", "..2026-10", "2026..2027"):
            with self.subTest(text=text):
                self.assertInvalid(text)

    def test_multiple_separators_are_invalid(self):
        for text in (
            "2026-01-01..2026-01-02..",
            "2026-01-01..2026-01-02..2026-01-03",
            "2026-01-01 ... 2026-01-02",
        ):
            with self.subTest(text=text):
                self.assertInvalid(text)

    def test_whitespace_other_than_spaces_is_invalid(self):
        for text in (
            "\t2026-10-01",
            "2026-10-01\t",
            "2026-10-01\t..\t2026-10-31",
            "2026-10-01\n..2026-10-31",
            "2026 -10-01..2026-10-31",
        ):
            with self.subTest(text=text):
                self.assertInvalid(text)

